package main

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"reflect"
	"slices"
	"strconv"
	"strings"
)

// json: encoding/json against gostd::json. Inputs: "strings" (length-prefixed records, 4-byte
// big-endian length then the bytes: all 256 one-byte strings, then 5,000 generated byte
// strings), "floats" (50,000 bit patterns, one 16-digit hex number per line) and "docs-NNN" (20
// files of 500 length-prefixed JSON documents, about 15% of them invalid), "docs-edge" (closes
// past the top level followed by a new value), "raw" (length-prefixed RawMessage values, see
// jsRawDocs), and "typed-<shape>-NNN" (60 per shape in jsShapes, one JSON document each,
// following a graphify-go type: see jsTyped).
//
// Ops: strings: html, nohtml; floats: json; raw: marshal (json.Marshal of jsRawField, or the
// error); docs: valid, compact, compact_html, indent. Every
// op's output is one line per input, except indent, which writes one length-prefixed record per
// document (an error is 0x00 then the error text). An error in the other ops is its text in the
// line. typed: unmarshal (json.Unmarshal into a new value: the error text, or empty), value
// (json.Marshal of the value after Unmarshal, error or not), indent (json.MarshalIndent of it,
// prefix "", indent two spaces); rpc also encode (serve.go's reply through an Encoder).
// That is 2 + 1 + 1 + 20*4 + 4 + 6*60*3 + 60 = 1228 output files.

func init() {
	register("json", 1228, jsGen, jsRun)
}

// graphify-go internal/query/query.go:22-97: graph.json as query.Load and Validate read it
// (Unmarshal at query.go:113 and validate.go:27, error "parsing %s: %w"). The unexported fields
// (byID, adj, edge) are left out: encoding/json ignores them.
type Graph struct {
	Nodes []Node     `json:"nodes"`
	Links []Link     `json:"links"`
	Attrs GraphAttrs `json:"graph"`

	BuiltAtCommit string `json:"built_at_commit,omitempty"`
	Path          string `json:"-"` // file Load read, for git lookups
}

type GraphAttrs struct {
	UnclassifiedFiles int            `json:"unclassified_files"`
	UnclassifiedExts  map[string]int `json:"unclassified_extensions"`
}

type Node struct {
	ID             string            `json:"id"`
	Label          string            `json:"label"`
	FileType       string            `json:"file_type"`
	SourceFile     string            `json:"source_file"`
	SourceLocation string            `json:"source_location"`
	Community      *int              `json:"community"`
	NormLabel      string            `json:"norm_label"`
	ComputedName   string            `json:"computed_name"`
	Attributes     map[string]string `json:"attributes"`
}

type Link struct {
	Source         string `json:"source"`
	Target         string `json:"target"`
	Relation       string `json:"relation"`
	Confidence     string `json:"confidence"`
	SourceFile     string `json:"source_file"`
	SourceLocation string `json:"source_location"`
}

// graphify-go internal/export/export.go:39-78: graph.json as ToJSON writes it (MarshalIndent
// at export.go:141).
type jsonNode struct {
	ID             string            `json:"id"`
	Label          string            `json:"label"`
	FileType       string            `json:"file_type"`
	SourceFile     string            `json:"source_file"`
	SourceLocation string            `json:"source_location,omitempty"`
	Community      *int              `json:"community"`
	NormLabel      string            `json:"norm_label"`
	ComputedName   string            `json:"computed_name,omitempty"`
	Attributes     map[string]string `json:"attributes,omitempty"`
}

type jsonLink struct {
	Source          string  `json:"source"`
	Target          string  `json:"target"`
	Relation        string  `json:"relation"`
	Confidence      string  `json:"confidence"`
	SourceFile      string  `json:"source_file,omitempty"`
	SourceLocation  string  `json:"source_location,omitempty"`
	Weight          float64 `json:"weight,omitempty"`
	ConfidenceScore float64 `json:"confidence_score"`
}

type graphAttrs struct {
	UnclassifiedFiles int            `json:"unclassified_files"`
	UnclassifiedExts  map[string]int `json:"unclassified_extensions,omitempty"`
}

type jsonGraph struct {
	Directed      bool       `json:"directed"`
	Multigraph    bool       `json:"multigraph"`
	Graph         graphAttrs `json:"graph"`
	Nodes         []jsonNode `json:"nodes"`
	Links         []jsonLink `json:"links"`
	Hyperedges    []any      `json:"hyperedges"`
	BuiltAtCommit string     `json:"built_at_commit,omitempty"`
}

// graphify-go internal/query/merge.go:21-29: graph.json as Merge reads it (Unmarshal at
// merge.go:116, error "parsing %s: %w") and writes it back (MarshalIndent at merge.go:94).
type rawGraph struct {
	Directed      bool              `json:"directed"`
	Multigraph    bool              `json:"multigraph"`
	Graph         json.RawMessage   `json:"graph"`
	Nodes         []json.RawMessage `json:"nodes"`
	Links         []json.RawMessage `json:"links"`
	Hyperedges    json.RawMessage   `json:"hyperedges,omitempty"`
	BuiltAtCommit json.RawMessage   `json:"built_at_commit,omitempty"`
}

// graphify-go cmd/graphify/serve.go:131-148: the MCP JSON-RPC messages (Unmarshal of a request
// at serve.go:178, Encoder of the response at serve.go:155-160).
type rpcRequest struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params,omitempty"`
}

type rpcResponse struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Result  any             `json:"result,omitempty"`
	Error   *rpcError       `json:"error,omitempty"`
}

type rpcError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// graphify-go internal/cache/cache.go:43-48, 93, 113-116: the stat sidecar (Unmarshal at
// cache.go:151, Marshal at cache.go:159).
type StatEntry struct {
	Size        int64  `json:"size"`
	MtimeNs     int64  `json:"mtime_ns"`
	Hash        string `json:"hash"`
	IndexedAtNs int64  `json:"indexed_at_ns"`
}

type StatIndex map[string]StatEntry

type statFile struct {
	V     string    `json:"v"`
	Files StatIndex `json:"files"`
}

// jsShapes are the typed-input shapes. mcp is graphify-go internal/extract/mcpconfig.go:44
// (a config file into map[string]json.RawMessage).
var jsShapes = []struct {
	name string
	zero func() any // a pointer to a new value
}{
	{"export", func() any { return new(jsonGraph) }},
	{"graph", func() any { return new(Graph) }},
	{"mcp", func() any { return new(map[string]json.RawMessage) }},
	{"rawgraph", func() any { return new(rawGraph) }},
	{"rpc", func() any { return new(rpcRequest) }},
	{"stat", func() any { return new(statFile) }},
}

const jsTypedPer = 60

// jsStrAlphabet: printable ASCII, the HTML characters, quote and backslash, control bytes, Latin-1
// and other valid UTF-8 (the line and paragraph separators, U+FFFD, an emoji) and invalid UTF-8.
var jsStrAlphabet = []string{
	"a", "Z", "0", " ", "~", "!", "<", ">", "&", "\"", "\\", "\x00", "\x01", "\x07", "\x08", "\t",
	"\n", "\x0b", "\x0c", "\r", "\x1f", "\x7f", "é", "ß", "日", " ", " ", "�",
	"\U0001F600", "\x80", "\xff", "\xe2\x82", "\xc0\x80", "\xed\xa0\x80",
}

// jsPieces are the fragments of a string in a generated document. The three HTML escapes are
// built by concatenation so that no source line holds one as six characters.
var jsPieces = []string{
	"a", "b", " ", "x1", "é", "日", "<", ">", "&", " ", "\xff",
	`\"`, `\\`, `\/`, `\b`, `\f`, `\n`, `\r`, `\t`, `é`, `😀`, `\ud800`, ` `,
	`\u0000`, `\u001f`, `\u007f`, `\u00` + "26", `\u00` + "3c", `\u00` + "3e",
}

var jsNumbers = []string{
	"0", "-0", "1", "-1", "12345", "1e5", "1.5E-3", "0.5", "-0.0", "1E+2", "0e0", "1e400",
	"123456789012345678901234567890",
}

var jsSpaces = []string{"", "", "", " ", "\t", "\r", "\n", " \n\t", "\r\n"}

func jsWrite(dir, name string, b []byte) error {
	return os.WriteFile(filepath.Join(dir, name), b, 0o644)
}

func jsFrame(b, rec []byte) []byte {
	return append(binary.BigEndian.AppendUint32(b, uint32(len(rec))), rec...)
}

func jsGen(dir string) error {
	if err := jsWrite(dir, "strings", jsStrings()); err != nil {
		return err
	}
	if err := jsWrite(dir, "floats", jsFloats()); err != nil {
		return err
	}
	for i := 0; i < 20; i++ {
		name := fmt.Sprintf("docs-%03d", i)
		r := seed("json/" + name)
		var b []byte
		for j := 0; j < 500; j++ {
			b = jsFrame(b, jsDoc(r))
		}
		if err := jsWrite(dir, name, b); err != nil {
			return err
		}
	}
	// docs-edge: a close past the top level, then more input that opens a new value. Go's
	// appendIndent takes depth to -1 on the stray close; gostd saturates at 0. The scanner
	// errors on the next byte and Indent discards the output, so both must give Go's error.
	var e []byte
	for _, d := range jsEdgeDocs {
		e = jsFrame(e, []byte(d))
	}
	if err := jsWrite(dir, "docs-edge", e); err != nil {
		return err
	}
	var raw []byte
	for _, d := range jsRawDocs {
		raw = jsFrame(raw, []byte(d))
	}
	if err := jsWrite(dir, "raw", raw); err != nil {
		return err
	}
	for _, s := range jsShapes {
		t := reflect.TypeOf(s.zero()).Elem()
		for i := 0; i < jsTypedPer; i++ {
			name := fmt.Sprintf("typed-%s-%03d", s.name, i)
			if err := jsWrite(dir, name, jsTypedDoc(seed("json/"+name), t)); err != nil {
				return err
			}
		}
	}
	return nil
}

var jsEdgeDocs = []string{
	"{}}", "[]]", "1]", "{}}{\"a\":[1,{\"b\":2}]}", "[]][[[1]]]", "1]{}", "\"s\"}[{}]",
	"{\"a\":1}}{\"b\":{\"c\":[]}}", "[[]]]]{{", "{} }\n{\n}", "0 ] [ ]", "null}}}{\"x\":1}",
}

// raw: RawMessage field values, mostly invalid. Marshal wraps the syntax error in a
// MarshalerError for *jsontext.Value (RawMessage is an alias of jsontext.Value).
var jsRawDocs = []string{
	"{", "1 2", "\"\xff\"", "[1,]", "tru", "{\"a\" 1}", "\"\\u12\"", " [ 1 , \"<&>\" ] ",
}

// jsRawField is a struct with a RawMessage field, as rawGraph and rpcRequest have.
type jsRawField struct {
	M json.RawMessage
}

func jsStrings() []byte {
	r := seed("json/strings")
	var b []byte
	for c := 0; c < 256; c++ {
		b = jsFrame(b, []byte{byte(c)})
	}
	for i := 0; i < 5000; i++ {
		var s []byte
		for n := r.intn(41); n > 0; n-- {
			s = append(s, jsStrAlphabet[r.intn(len(jsStrAlphabet))]...)
		}
		b = jsFrame(b, s)
	}
	return b
}

func jsFloats() []byte {
	const total = 50000
	r := seed("json/floats")
	var v []uint64
	bits := math.Float64bits
	add := func(b uint64) { v = append(v, b, b|1<<63) }
	around := func(f float64) {
		b := bits(f)
		add(b)
		for d := uint64(1); d <= 3; d++ {
			add(b + d)
			add(b - d)
		}
	}
	add(0)
	add(bits(math.MaxFloat64))
	add(bits(math.SmallestNonzeroFloat64))
	add(bits(math.Inf(1)))
	add(bits(math.NaN()))
	around(1e-6)
	around(1e21)
	for n := -323; n <= 308; n++ {
		f, _ := strconv.ParseFloat("1e"+strconv.Itoa(n), 64)
		add(bits(f))
	}
	for _, f := range []float64{1e-9, 1e-10, 1e20, 1e22} {
		add(bits(f))
	}
	for len(v) < total {
		v = append(v, r.next())
	}
	var b strings.Builder
	for _, x := range v {
		fmt.Fprintf(&b, "%016x\n", x)
	}
	return []byte(b.String())
}

func jsWS(r *rng, b *strings.Builder) { b.WriteString(jsSpaces[r.intn(len(jsSpaces))]) }

func jsStr(r *rng, b *strings.Builder) {
	b.WriteByte('"')
	for n := r.intn(8); n > 0; n-- {
		b.WriteString(jsPieces[r.intn(len(jsPieces))])
	}
	b.WriteByte('"')
}

// jsValue writes a valid JSON value, nesting containers at most max deep.
func jsValue(r *rng, b *strings.Builder, depth, max int) {
	k := r.intn(10)
	switch {
	case depth < max && k < 3:
		b.WriteByte('{')
		jsWS(r, b)
		for n := r.intn(4); n > 0; n-- {
			jsStr(r, b)
			jsWS(r, b)
			b.WriteByte(':')
			jsWS(r, b)
			jsValue(r, b, depth+1, max)
			jsWS(r, b)
			if n > 1 {
				b.WriteByte(',')
				jsWS(r, b)
			}
		}
		b.WriteByte('}')
	case depth < max && k < 6:
		b.WriteByte('[')
		jsWS(r, b)
		for n := r.intn(4); n > 0; n-- {
			jsValue(r, b, depth+1, max)
			jsWS(r, b)
			if n > 1 {
				b.WriteByte(',')
				jsWS(r, b)
			}
		}
		b.WriteByte(']')
	default:
		switch r.intn(5) {
		case 0:
			jsStr(r, b)
		case 1:
			b.WriteString(jsNumbers[r.intn(len(jsNumbers))])
		case 2:
			b.WriteString(strconv.Itoa(r.intn(2000) - 1000))
		case 3:
			b.WriteString([]string{"true", "false"}[r.intn(2)])
		default:
			b.WriteString("null")
		}
	}
}

// jsDoc is a valid document, or (about 15% of the time) a damaged one.
func jsDoc(r *rng) []byte {
	var b strings.Builder
	jsWS(r, &b)
	jsValue(r, &b, 0, 1+r.intn(12))
	jsWS(r, &b)
	d := []byte(b.String())
	if r.intn(100) >= 15 {
		return d
	}
	return jsDamage(r, d)
}

// jsDamage breaks a document: cut short, a bit flipped, a trailing byte, a BOM, a stray comma,
// or an unterminated string.
func jsDamage(r *rng, d []byte) []byte {
	switch r.intn(6) {
	case 0:
		return d[:r.intn(len(d)+1)]
	case 1:
		if len(d) > 0 {
			d[r.intn(len(d))] ^= 1 << r.intn(8)
		}
		return d
	case 2:
		return append(d, []string{"x", "}", "]", ",", "1", " x"}[r.intn(6)]...)
	case 3:
		return append([]byte("\xef\xbb\xbf"), d...)
	case 4:
		i := r.intn(len(d) + 1)
		return append(d[:i:i], append([]byte(","), d[i:]...)...)
	default:
		return []byte(`{"k": "unterminated`)
	}
}

func jsRecords(in []byte) [][]byte {
	var v [][]byte
	for len(in) >= 4 {
		n := int(binary.BigEndian.Uint32(in))
		v = append(v, in[4:4+n])
		in = in[4+n:]
	}
	return v
}

var (
	jsRawType = reflect.TypeOf(json.RawMessage(nil))
	jsAnyType = reflect.TypeOf((*any)(nil)).Elem()
)

// jsTypedInts and jsTypedFloats are the numbers of int and float64 fields: in range, out of
// range, a fraction or exponent where an int is wanted, and the float formatting edges.
var jsTypedInts = []string{
	"0", "-0", "1", "-1", "42", "2147483648", "9007199254740993", "9223372036854775807",
	"-9223372036854775808", "9223372036854775808", "-9223372036854775809",
	"18446744073709551616", "1e2", "1.0", "1.5", "-1E-7", "0.0",
}

var jsTypedFloats = []string{
	"0", "-0", "0.0", "-0.0", "1", "0.5", "0.1", "1e20", "1e21", "1e-6", "1e-7", "-1e-7", "1E+2",
	"123456789", "9007199254740993", "123456789012345678901234567890", "5e-324", "1e-400",
	"1.7976931348623157e308", "1e400", "-1e400",
}

// jsUnknownKeys are member names no struct field has ("-" and "Path" name the json:"-" field).
var jsUnknownKeys = []string{"Path", "-", "x", "byID", "", "nodes ", "hyperedges"}

// jsTypedDoc is a document for Go type t, damaged 12% of the time.
func jsTypedDoc(r *rng, t reflect.Type) []byte {
	var b strings.Builder
	jsWS(r, &b)
	jsTyped(r, &b, t)
	jsWS(r, &b)
	d := []byte(b.String())
	if r.intn(100) < 12 {
		return jsDamage(r, d)
	}
	return d
}

// jsTyped writes a value for Go type t: 4% a random value (usually of the wrong kind), 3% null,
// else one of t's kind. Struct members are sometimes missing, repeated, renamed to a variant
// (jsKey), joined by an unknown member or written in reverse order.
func jsTyped(r *rng, b *strings.Builder, t reflect.Type) {
	switch k := r.intn(100); {
	case k < 4:
		jsValue(r, b, 0, 2)
		return
	case k < 7:
		b.WriteString("null")
		return
	}
	if t == jsRawType || t.Kind() == reflect.Interface {
		jsValue(r, b, 0, 4)
		return
	}
	switch t.Kind() {
	case reflect.String:
		jsStr(r, b)
	case reflect.Bool:
		b.WriteString([]string{"true", "false"}[r.intn(2)])
	case reflect.Int, reflect.Int64:
		b.WriteString(jsTypedInts[r.intn(len(jsTypedInts))])
	case reflect.Float64:
		b.WriteString(jsTypedFloats[r.intn(len(jsTypedFloats))])
	case reflect.Pointer:
		jsTyped(r, b, t.Elem())
	case reflect.Slice:
		var items []func()
		for n := r.intn(5); n > 0; n-- {
			items = append(items, func() { jsTyped(r, b, t.Elem()) })
		}
		jsList(r, b, '[', ']', items)
	case reflect.Map:
		var items []func()
		for n := r.intn(5); n > 0; n-- {
			items = append(items, func() {
				var k strings.Builder
				jsStr(r, &k)
				jsMember(r, b, k.String(), t.Elem())
			})
		}
		jsList(r, b, '{', '}', items)
	case reflect.Struct:
		var items []func()
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			name, _, _ := strings.Cut(f.Tag.Get("json"), ",")
			if name == "-" || r.intn(10) == 0 {
				continue
			}
			// One member in 20 is repeated.
			for n := 1 + r.intn(20)/19; n > 0; n-- {
				items = append(items, func() { jsMember(r, b, `"`+jsKey(r, name)+`"`, f.Type) })
			}
		}
		if r.intn(6) == 0 {
			items = append(items, func() {
				jsMember(r, b, `"`+jsUnknownKeys[r.intn(len(jsUnknownKeys))]+`"`, jsAnyType)
			})
		}
		if r.intn(4) == 0 {
			slices.Reverse(items)
		}
		jsList(r, b, '{', '}', items)
	default:
		panic("jsTyped: no generator for " + t.String())
	}
}

// jsKey is the JSON name for a field: usually its tag name, sometimes a variant that
// strings.EqualFold matches (upper case, a capital first letter, U+017F for s, U+212A for k) or
// one that matches no field (underscores dropped).
func jsKey(r *rng, name string) string {
	switch r.intn(16) {
	case 0:
		return strings.ToUpper(name)
	case 1:
		return strings.ToUpper(name[:1]) + name[1:]
	case 2:
		return strings.ReplaceAll(name, "s", string(rune(0x017f)))
	case 3:
		return strings.ReplaceAll(name, "k", string(rune(0x212a)))
	case 4:
		return strings.ReplaceAll(name, "_", "")
	}
	return name
}

// jsMember writes key (quoted JSON text), a colon and a value for Go type t.
func jsMember(r *rng, b *strings.Builder, key string, t reflect.Type) {
	b.WriteString(key)
	jsWS(r, b)
	b.WriteByte(':')
	jsWS(r, b)
	jsTyped(r, b, t)
}

// jsList writes the items between open and end, with commas and random whitespace.
func jsList(r *rng, b *strings.Builder, open, end byte, items []func()) {
	b.WriteByte(open)
	jsWS(r, b)
	for i, f := range items {
		if i > 0 {
			b.WriteByte(',')
			jsWS(r, b)
		}
		f()
		jsWS(r, b)
	}
	b.WriteByte(end)
}

func jsResult(out []byte, err error) result {
	if err != nil {
		return result{err: err.Error()}
	}
	return result{out: out}
}

// jsTypedRun runs the typed ops on one input; the shape is the case name between "typed-" and
// the last "-".
func jsTypedRun(name string, in []byte) []op {
	shape := strings.TrimPrefix(name[:strings.LastIndexByte(name, '-')], "typed-")
	for _, s := range jsShapes {
		if s.name != shape {
			continue
		}
		v := s.zero()
		uerr := json.Unmarshal(in, v)
		m, merr := json.Marshal(v)
		ind, ierr := json.MarshalIndent(v, "", "  ")
		ops := []op{
			{"unmarshal", jsResult(nil, uerr)}, {"value", jsResult(m, merr)},
			{"indent", jsResult(ind, ierr)},
		}
		if req, ok := v.(*rpcRequest); ok {
			ops = append(ops, op{"encode", jsReply(req, uerr)})
		}
		return ops
	}
	return nil
}

// jsReply is serve.go's handle (:176-201) for a request that names no known method: the
// parse-error response if Unmarshal failed, else "method not found" with the request's id,
// written by an Encoder as run (:155-160) does.
func jsReply(req *rpcRequest, uerr error) result {
	resp := rpcResponse{JSONRPC: "2.0", Error: &rpcError{Code: -32700, Message: "parse error"}}
	if uerr == nil {
		resp.ID = req.ID
		resp.Error = &rpcError{Code: -32601, Message: "method not found: " + req.Method}
	}
	var buf bytes.Buffer
	err := json.NewEncoder(&buf).Encode(resp)
	return jsResult(buf.Bytes(), err)
}

func jsRun(name string, in []byte) []op {
	switch {
	case strings.HasPrefix(name, "typed-"):
		return jsTypedRun(name, in)
	case name == "strings":
		var html, nohtml []byte
		for _, s := range jsRecords(in) {
			m, _ := json.Marshal(string(s))
			html = append(append(html, m...), '\n')
			var buf bytes.Buffer
			enc := json.NewEncoder(&buf)
			enc.SetEscapeHTML(false)
			enc.Encode(string(s))
			nohtml = append(append(nohtml, bytes.TrimSuffix(buf.Bytes(), []byte("\n"))...), '\n')
		}
		return []op{{"html", result{out: html}}, {"nohtml", result{out: nohtml}}}
	case name == "floats":
		var out []byte
		for _, l := range strings.Split(strings.TrimSuffix(string(in), "\n"), "\n") {
			x, err := strconv.ParseUint(l, 16, 64)
			if err != nil {
				panic(err)
			}
			m, err := json.Marshal(math.Float64frombits(x))
			if err != nil {
				m = []byte(err.Error())
			}
			out = append(append(out, m...), '\n')
		}
		return []op{{"json", result{out: out}}}
	case name == "raw":
		var out []byte
		for _, d := range jsRecords(in) {
			m, err := json.Marshal(jsRawField{M: d})
			if err != nil {
				m = []byte(err.Error())
			}
			out = append(append(out, m...), '\n')
		}
		return []op{{"marshal", result{out: out}}}
	case strings.HasPrefix(name, "docs-"):
		var valid, compact, compactHTML, indent []byte
		for _, d := range jsRecords(in) {
			valid = append(valid, bit(json.Valid(d)), '\n')
			var c bytes.Buffer
			if err := json.Compact(&c, d); err != nil {
				e := []byte(err.Error())
				compact = append(append(compact, e...), '\n')
				compactHTML = append(append(compactHTML, e...), '\n')
			} else {
				compact = append(append(compact, c.Bytes()...), '\n')
				var h bytes.Buffer
				json.HTMLEscape(&h, c.Bytes())
				compactHTML = append(append(compactHTML, h.Bytes()...), '\n')
			}
			var ind bytes.Buffer
			if err := json.Indent(&ind, d, ">", "\t"); err != nil {
				indent = jsFrame(indent, append([]byte{0}, err.Error()...))
			} else {
				indent = jsFrame(indent, ind.Bytes())
			}
		}
		return []op{
			{"valid", result{out: valid}}, {"compact", result{out: compact}},
			{"compact_html", result{out: compactHTML}}, {"indent", result{out: indent}},
		}
	}
	return nil
}
